Proceso PromedioDePrecios
    Definir precio1 Como Entero;
    Definir precio2 Como Entero;
    Definir promedio Como Real;
    Leer precio1;
    Leer precio2;
    promedio <- (precio1 + precio2) / 2;
    Escribir promedio;
FinProceso

